# changes/165-goal-replay-on-ice.py - goal replay: every player and the puck moving, like NHL EDGE, with who was on the ice at the goal and their plus/minus. gm_edge.py saves the NHL tracking each sync (edge/); the app plays it in the goal visualizer

GM_EDGE = '"""gm_edge.py - change 165: saves the NHL EDGE tracking (where every player and the puck are) for each goal of today\'s games,\nso the app can replay it and list who was on the ice at the goal (plus/minus).\n\nRuns at the end of every sync (from gm_notify.py). Writes edge/index.json and one small file per goal (edge/<game>-<event>.json).\nThe NHL only sends these files to requests that come from nhl.com, so the browser cannot read them itself; this script fetches them.\nKeeps 3 days.\n"""\nimport json, os, time, glob\nfrom datetime import datetime, timedelta, timezone\nimport requests\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nDIR = os.path.join(HERE, "edge")\nIDX = os.path.join(DIR, "index.json")\nUA = {"User-Agent": "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1"}\nNHL = dict(UA, Referer="https://www.nhl.com/", Origin="https://www.nhl.com")\nAL = {"LAK": "LA", "NJD": "NJ", "SJS": "SJ", "TBL": "TB", "UTAH": "UTA", "ARI": "UTA"}\nKEEP_DAYS = 3\nBUDGET_S = 50\n\n\ndef ab(x):\n    x = str(x or "").upper()\n    return AL.get(x, x)\n\n\ndef getj(url, hdr=None):\n    r = requests.get(url, headers=hdr or UA, timeout=20)\n    r.raise_for_status()\n    return r.json()\n\n\ndef pack(frames):\n    """frames -> [[ms, [[pid, team, num, x, y], ...]], ...] with x, y in feet from centre ice (x -100..100, y -42.5..42.5)"""\n    out, t0 = [], None\n    for f in frames:\n        ts = f.get("timeStamp") or 0\n        if t0 is None:\n            t0 = ts\n        row = []\n        for o in (f.get("onIce") or {}).values():\n            try:\n                x, y = round(float(o["x"]) / 12 - 100, 1), round(float(o["y"]) / 12 - 42.5, 1)\n            except Exception:\n                continue\n            pid = o.get("playerId") or 0\n            row.append([pid if pid != "" else 0, ab(o.get("teamAbbrev")), o.get("sweaterNumber") or 0, x, y])\n        out.append([round((ts - t0) / 10), row])  # timeStamp is in 1/10000 s\n    return out\n\n\ndef goal_frame(fr):\n    """index of the frame where the puck is closest to either net (the goal); last frame if no puck"""\n    best, bi = None, len(fr) - 1\n    for i, (_, row) in enumerate(fr):\n        for o in row:\n            if o[0] == 0:\n                d = min((o[3] - 89) ** 2 + o[4] ** 2, (o[3] + 89) ** 2 + o[4] ** 2)\n                if best is None or d < best - 0.01:\n                    best, bi = d, i\n    return bi\n\n\ndef run():\n    os.makedirs(DIR, exist_ok=True)\n    try:\n        idx = json.load(open(IDX))\n    except Exception:\n        idx = {"goals": {}}\n    G = idx.setdefault("goals", {})\n    t0, new = time.time(), 0\n    days = set()\n    try:\n        now = getj("https://api-web.nhle.com/v1/score/now")\n    except Exception as ex:\n        print(f"(edge) score/now failed: {ex}")\n        return\n    for g in now.get("games") or []:\n        if g.get("gameState") not in ("LIVE", "CRIT", "FINAL", "OFF") or not g.get("id"):\n            continue\n        gid, day = g["id"], g.get("gameDate") or ""\n        days.add(day)\n        if time.time() - t0 > BUDGET_S:\n            break\n        try:\n            pbp = getj(f"https://api-web.nhle.com/v1/gamecenter/{gid}/play-by-play")\n        except Exception as ex:\n            print(f"(edge) play-by-play {gid} failed: {ex}")\n            continue\n        tid = {}\n        for side in ("homeTeam", "awayTeam"):\n            T = pbp.get(side) or {}\n            tid[T.get("id")] = ab(T.get("abbrev"))\n        ro = {}\n        for r in pbp.get("rosterSpots") or []:\n            nm = (((r.get("firstName") or {}).get("default") or "") + " " + ((r.get("lastName") or {}).get("default") or "")).strip()\n            ro[str(r.get("playerId"))] = [nm, r.get("positionCode") or "", r.get("sweaterNumber"), tid.get(r.get("teamId"), "")]\n        for p in pbp.get("plays") or []:\n            if p.get("typeDescKey") != "goal" or not p.get("pptReplayUrl"):\n                continue\n            key = f"{gid}-{p.get(\'eventId\')}"\n            old = G.get(key) or {}\n            if old.get("ok") or (old.get("tries", 0) >= 6) or time.time() - old.get("at", 0) < 240:\n                continue\n            if time.time() - t0 > BUDGET_S:\n                break\n            d = p.get("details") or {}\n            ent = {"d": day, "g": gid, "ev": p.get("eventId"), "per": (p.get("periodDescriptor") or {}).get("number"),\n                   "t": p.get("timeInPeriod"), "tr": p.get("timeRemaining"), "team": tid.get(d.get("eventOwnerTeamId"), ""),\n                   "sc": p.get("situationCode"), "home": tid.get((pbp.get("homeTeam") or {}).get("id"), ""),\n                   "at": time.time(), "tries": old.get("tries", 0) + 1, "ok": False}\n            try:\n                r = requests.get(p["pptReplayUrl"], headers=NHL, timeout=20)\n                fr = r.json() if r.status_code == 200 else None\n            except Exception:\n                fr = None\n            if isinstance(fr, list) and fr:\n                P = pack(fr)\n                gi = goal_frame(P)\n                ids = set(str(o[0]) for f in P for o in f[1] if o[0])\n                with open(os.path.join(DIR, key + ".json"), "w") as f:\n                    json.dump({"f": P, "gi": gi, "ro": {k: ro[k] for k in ids if k in ro}, "home": ent["home"], "team": ent["team"],\n                               "sc": ent["sc"], "goalie": d.get("goalieInNetId"), "scorer": d.get("scoringPlayerId"),\n                               "a1": d.get("assist1PlayerId"), "a2": d.get("assist2PlayerId")}, f, separators=(",", ":"))\n                ent["ok"] = True\n                new += 1\n            G[key] = ent\n    # keep 3 days\n    cut = (datetime.now(timezone.utc) - timedelta(days=KEEP_DAYS)).strftime("%Y-%m-%d")\n    for k in [k for k, v in G.items() if (v.get("d") or "") < cut]:\n        G.pop(k, None)\n        try:\n            os.remove(os.path.join(DIR, k + ".json"))\n        except Exception:\n            pass\n    for f in glob.glob(os.path.join(DIR, "*-*.json")):\n        if os.path.basename(f)[:-5] not in G:\n            os.remove(f)\n    idx["updated"] = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")\n    with open(IDX, "w") as f:\n        json.dump(idx, f, separators=(",", ":"))\n    print(f"(edge) {new} new goal replay(s), {sum(1 for v in G.values() if v.get(\'ok\'))} saved")\n\n\nif __name__ == "__main__":\n    run()\n'

HELP = '// ---------- change 165: goal replay with every player on the ice (NHL EDGE tracking saved by gm_edge.py) (install.py) ----------\nconst E165 = { idx: null, at: 0, busy: false, files: {} };\nfunction gxEdgeLoad165() {\n  if (E165.busy || Date.now() - E165.at < 60000) return;\n  E165.busy = true;\n  fetch("edge/index.json?t=" + Date.now()).then((r) => (r.ok ? r.json() : null)).catch(() => null).then((j) => {\n    E165.busy = false; E165.at = Date.now();\n    if (j) { E165.idx = j; window.dispatchEvent(new Event("gx-edge165")); }\n  });\n}\nconst gxSec165 = (t) => { const m = String(t || "").split(":"); return (+m[0] || 0) * 60 + (+m[1] || 0); };\nfunction gxEdgeFind165(x, g, tm) {\n  const I = E165.idx;\n  if (!I || !x) return null;\n  const per = (x.periodDescriptor || {}).number || 1, sec = gxSec165(x.timeInPeriod), day = (g || {}).gameDate;\n  let best = null;\n  Object.entries(I.goals || {}).forEach(([k, v]) => {\n    if (!v.ok || v.team !== tm || v.per !== per || (day && v.d && v.d !== day)) return;\n    const d = Math.min(Math.abs(gxSec165(v.t) - sec), Math.abs(gxSec165(v.tr) - sec));\n    if (d <= 3 && (!best || d < best.d)) best = { k, v, d };\n  });\n  return best;\n}\nfunction useEdge165(x, g, tm) {\n  const [, t] = useState(0);\n  useEffect(() => {\n    const f = () => t((n) => n + 1);\n    window.addEventListener("gx-edge165", f); gxEdgeLoad165();\n    const id = setInterval(gxEdgeLoad165, 60000);\n    return () => { window.removeEventListener("gx-edge165", f); clearInterval(id); };\n  }, []);\n  const m = gxEdgeFind165(x, g, tm);\n  if (!m) return null;\n  const F = E165.files[m.k];\n  if (F === undefined) {\n    E165.files[m.k] = null;\n    fetch("edge/" + m.k + ".json").then((r) => (r.ok ? r.json() : false)).catch(() => false).then((j) => { E165.files[m.k] = j || false; window.dispatchEvent(new Event("gx-edge165")); });\n    return null;\n  }\n  return F ? { k: m.k, v: m.v, F } : null;\n}\nfunction gxRinkBg165() {\n  const red = "#d64545", blue = "#3d73d9", ln = "var(--line2, var(--line))";\n  const out = [\n    <rect key="b" x="-100" y="-42.5" width="200" height="85" rx="28" fill="var(--card2, var(--bg))" stroke={ln} strokeWidth="1" />,\n    <line key="c" x1="0" y1="-42.5" x2="0" y2="42.5" stroke={red} strokeWidth="1" strokeDasharray="2 1.5" />,\n    <line key="bl" x1="-25" y1="-42.5" x2="-25" y2="42.5" stroke={blue} strokeWidth="1.2" />,\n    <line key="br" x1="25" y1="-42.5" x2="25" y2="42.5" stroke={blue} strokeWidth="1.2" />,\n    <line key="gl" x1="-89" y1="-38.5" x2="-89" y2="38.5" stroke={red} strokeWidth="0.5" />,\n    <line key="gr" x1="89" y1="-38.5" x2="89" y2="38.5" stroke={red} strokeWidth="0.5" />,\n    <circle key="cc" cx="0" cy="0" r="15" fill="none" stroke={blue} strokeWidth="0.6" opacity=".7" />,\n    <rect key="nl" x="-92.3" y="-3" width="3.3" height="6" fill="none" stroke={red} strokeWidth="0.6" />,\n    <rect key="nr" x="89" y="-3" width="3.3" height="6" fill="none" stroke={red} strokeWidth="0.6" />,\n  ];\n  [[-69, -22], [-69, 22], [69, -22], [69, 22]].forEach(([a, b], i) => out.push(<circle key={"f" + i} cx={a} cy={b} r="15" fill="none" stroke={red} strokeWidth="0.6" opacity=".7" />));\n  return out;\n}\nfunction GxEdge165({ e, s, x }) {\n  const F = e.F, fr = F.f || [], n = fr.length, gi = Math.max(0, Math.min(F.gi == null ? n - 1 : F.gi, n - 1));\n  const D = n > 1 ? fr[n - 1][0] : 0, even = !(D > 2000 && D < 60000);\n  const tOf = (k) => (even ? k * 100 : fr[k][0]);\n  const [i, setI] = useState(0);\n  const [play, setPlay] = useState(true);\n  const [run, setRun] = useState(0);\n  useEffect(() => {\n    if (!play || n < 2) return undefined;\n    let k = i, raf = 0;\n    const t0 = performance.now() - tOf(k);\n    const step = (now) => {\n      const ms = now - t0;\n      while (k < n - 1 && tOf(k + 1) <= ms) k++;\n      setI(k);\n      if (k >= n - 1) { setPlay(false); return; }\n      raf = requestAnimationFrame(step);\n    };\n    raf = requestAnimationFrame(step);\n    return () => cancelAnimationFrame(raf);\n  }, [play, run]);\n  if (!n) return null;\n  const row = (fr[i] || [0, []])[1], scT = e.v.team || F.team, ro = F.ro || {};\n  const gRow = ((fr[gi] || [0, []])[1]).filter((o) => o[0]);\n  const code = String(F.sc || e.v.sc || ""), scHome = scT === (F.home || e.v.home);\n  const mySk = +(scHome ? code[2] : code[1]), opSk = +(scHome ? code[1] : code[2]);\n  const pp = code.length === 4 && mySk > opSk;\n  const isG = (o) => ((ro[o[0]] || [])[1] || "") === "G";\n  const teams = [scT].concat([...new Set(gRow.map((o) => o[1]))].filter((t) => t !== scT));\n  return (\n    <div className="gx-ed165" data-gx="165">\n      <svg viewBox="-102 -45 204 90" role="img" aria-label="Goal replay with every player on the ice">\n        {gxRinkBg165()}\n        {row.map((o, k) => (o[0] ? (\n          <g key={"p" + o[0]}><circle cx={o[3]} cy={o[4]} r="3.6" className={o[1] === scT ? "sc" : "ot"} /><text x={o[3]} y={o[4] + 1.25} textAnchor="middle" fontSize="3.4" className={o[1] === scT ? "sc" : "ot"}>{o[2]}</text></g>\n        ) : <circle key={"pk" + k} cx={o[3]} cy={o[4]} r="1.5" className="pk" />))}\n      </svg>\n      <div className="ct">\n        <button type="button" onClick={() => { setI(0); setPlay(true); setRun((r) => r + 1); }} aria-label="Replay">{"↻"}</button>\n        <button type="button" onClick={() => { if (i >= n - 1) setI(0); setPlay(!play); setRun((r) => r + 1); }}>{play ? "Pause" : "Play"}</button>\n        <button type="button" onClick={() => { setPlay(false); setI(gi); }}>Goal moment</button>\n        <span className="lg"><i className="sc"></i>{scT}<i className="ot"></i>{teams[1] || ""}</span>\n      </div>\n      <div className="ol">\n        <div className="hd">On the ice at the goal{pp ? " (power play, no plus/minus)" : ""}</div>\n        {teams.map((t) => (\n          <div key={t} className="tm"><div className="tn">{t + (t === scT ? " (scored)" : "")}</div>\n            {gRow.filter((o) => o[1] === t).sort((a, b) => (isG(a) ? 1 : 0) - (isG(b) ? 1 : 0) || a[2] - b[2]).map((o) => {\n              const r = ro[o[0]] || [], nm = r[0] || "#" + o[2], p = gxFind131(t, o[2], nm), tag = gxTag131(s, p);\n              const pm = isG(o) || pp || code.length !== 4 ? "" : t === scT ? "+1" : "-1";\n              return <div key={o[0]} className="pl"><span className="truncate">{"#" + o[2] + " "}{p && window.__NAV ? <button type="button" className="hover:underline" onClick={() => window.__NAV.player(p)}>{shortN(nm)}</button> : shortN(nm)}{isG(o) ? " (G)" : ""}{tag ? <span className="tg">{" (" + tag + ")"}</span> : null}</span><b>{pm}</b></div>;\n            })}\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n'

CSS = '  /* change 165 (install.py) */\n  .gx-ed165 svg { display: block; width: 100%; height: auto; }\n  .gx-ed165 circle.sc { fill: var(--accent); stroke: var(--ink); stroke-width: .4; }\n  .gx-ed165 circle.ot { fill: var(--card); stroke: var(--ink); stroke-width: .6; }\n  .gx-ed165 text { font-weight: 700; font-family: inherit; }\n  .gx-ed165 text.sc { fill: #fff; }\n  .gx-ed165 text.ot { fill: var(--ink); }\n  .gx-ed165 circle.pk { fill: var(--ink); stroke: var(--bg); stroke-width: .4; }\n  .gx-ed165 .ct { display: flex; align-items: center; gap: 6px; margin-top: 6px; flex-wrap: wrap; }\n  .gx-ed165 .ct button { padding: 5px 10px; border-radius: 8px; background: var(--card2, var(--bg)); box-shadow: inset 0 0 0 1px var(--line); font-size: 13px; }\n  .gx-ed165 .ct .lg { margin-left: auto; display: inline-flex; align-items: center; gap: 4px; font-size: 12px; color: var(--mute); }\n  .gx-ed165 .ct .lg i { display: inline-block; width: 10px; height: 10px; border-radius: 99px; margin-left: 6px; }\n  .gx-ed165 .ct .lg i.sc { background: var(--accent); }\n  .gx-ed165 .ct .lg i.ot { background: var(--card); box-shadow: inset 0 0 0 1.5px var(--ink); }\n  .gx-ed165 .ol { margin-top: 8px; display: grid; grid-template-columns: minmax(0,1fr) minmax(0,1fr); gap: 4px 12px; font-size: 13px; }\n  .gx-ed165 .ol .tm { min-width: 0; }\n  .gx-ed165 .ol .pl > span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n  .gx-ed165 .ol .hd { grid-column: 1 / -1; color: var(--mute); font-size: 12px; }\n  .gx-ed165 .ol .tn { font-weight: 600; margin-bottom: 2px; }\n  .gx-ed165 .ol .pl { display: flex; align-items: center; gap: 6px; line-height: 1.6; min-width: 0; }\n  .gx-ed165 .ol .pl > span { flex: 1; min-width: 0; }\n  .gx-ed165 .ol .pl .tg { color: var(--mute); }\n  .gx-ed165 .ol .pl b { font-weight: 600; width: 22px; text-align: right; flex: none; }\n</style>'

new_file("gm_edge.py", GM_EDGE)


def notify(t):
    return lit(t, "165: run gm_edge each sync",
               "        try:  # change 164: one-time EDGE tracking test\n            import gm_edge_probe\n            gm_edge_probe.run()\n",
               "        try:  # change 165: save NHL EDGE goal tracking for the app\n            import gm_edge\n            gm_edge.run()\n",
               "change 165: save NHL EDGE goal tracking")


def app(t):
    t = lit(t, "165: styles", "</style>", CSS, "change 165 (install.py)")
    t = lit(t, "165: helpers", ROOT, HELP + ROOT, "change 165: goal replay with every player")
    t = lit(t, "165: rink uses replay",
            "function GxRink163({ x, g, tm }) {\n  const cx = +x.cx, cy = +x.cy;\n  if (isNaN(cx) || isNaN(cy)) return null;",
            "function GxRink163({ x, g, tm, s }) {\n  const e165 = useEdge165(x, g, tm); /* gx165 */\n  const cx = +x.cx, cy = +x.cy;\n  if ((isNaN(cx) || isNaN(cy)) && !e165) return null;",
            "const e165 = useEdge165(x, g, tm); /* gx165 */")
    t = lit(t, "165: replay in place of the still rink (open)",
            '<svg viewBox="-102 -45 204 90" role="img" aria-label={"Goal by "',
            '{e165 ? <GxEdge165 key={e165.k} e={e165} s={s} x={x} /> : <svg viewBox="-102 -45 204 90" role="img" aria-label={"Goal by "',
            "<GxEdge165 key={e165.k} e={e165} s={s} x={x} /> : <svg")
    t = lit(t, "165: replay in place of the still rink (close)",
            'fontWeight="600">{tm}</text>\n      </svg>\n      <div className="tl">',
            'fontWeight="600">{tm}</text>\n      </svg>}\n      <div className="tl">',
            '</svg>}\n      <div className="tl">')
    t = lit(t, "165: pass the app state",
            "<GxRink163 x={r.x} g={r.g} tm={r.tm} />",
            "<GxRink163 x={r.x} g={r.g} tm={r.tm} s={s} />",
            None, count=2)
    return t


edit("gm_notify.py", notify)
edit(APP, app)
